/** One audit entry for an admin action, as stored for the SOC 2 evidence. */
export function auditEntry(req: AdminRequest, action: string, now: Date = new Date()): AuditEntry {
  return {
    timestamp: now.toISOString(),
    actor: req.actor,
    action,
    method: req.method,
    path: req.path,
    ip: req.headers["x-forwarded-for"] || req.headers["x-real-ip"] || null,
    user_agent: req.headers["user-agent"] || null,
    impersonated: req.headers["x-impersonate-org"] || null,
  };
}

