test("audit entry records actor and action", () => {
  const req = {
    method: "POST",
    path: "/admin/suspend",
    headers: { "user-agent": "curl/8.0", "x-forwarded-for": "203.0.113.42" },
    actor: "admin@kiln.example",
  };
  const entry = auditEntry(req, "suspend_org", new Date("2026-11-17T10:00:00Z"));
  assert.equal(entry.actor, "admin@kiln.example");
  assert.equal(entry.action, "suspend_org");
  assert.equal(entry.timestamp, "2026-11-17T10:00:00.000Z");
  assert.equal(entry.ip, "203.0.113.42");
});

test("impersonated is null when not impersonating", () => {
  const req = {
    method: "GET",
    path: "/admin/metrics",
    headers: {},
    actor: "admin@kiln.example",
  };
  const entry = auditEntry(req, "view_metrics");
  assert.equal(entry.impersonated, null);
});

test("impersonated is set when acting on behalf of an org", () => {
  const req = {
    method: "POST",
    path: "/jobs/enqueue",
    headers: { "x-impersonate-org": "acme" },
    actor: "support@kiln.example",
  };
  const entry = auditEntry(req, "enqueue_job");
  assert.equal(entry.actor, "support@kiln.example");
  assert.equal(entry.impersonated, "acme");
});

